// Generated by OrchestKit Claude Plugin
// Created: 2026-11-15

/**
 * Session stamp: ork_version and rules_hash on every session row.
 *
 * sessions.db carried ork_version NULL on 11534 of 11534 rows (2026-05-27 to
 * 2026-11-15). The resolver read `package.json` three levels above the bundle;
 * the installed plugin root holds `plugin.json` and `.claude-plugin/plugin.json`
 * there, no package.json, and the error was swallowed into NULL.
 *
 * Instrument rules these tests hold:
 *   - an unresolved manifest or an empty rule set is an explicit error value
 *     plus one log line, never NULL and never the hash of nothing;
 *   - one test reads the REAL installed plugin layout, not only a fixture.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';

import { sessionRegistrar, __internals } from '../../lifecycle/session-registrar.js';
import { computeRulesHash, RULES_HASH_EMPTY } from '../../lib/rules-hash.js';
import { __resetDbForTests } from '../../lib/session-registry.js';
import { NOOP_CTX } from '../../lib/context.js';
import type { HookContext, HookInput } from '../../types.js';

const { getOrkVersion, computeStamp, ORK_VERSION_UNRESOLVED } = __internals;

/** A HookContext that records every log line. */
function capturingCtx(lines: string[]): HookContext {
  return { ...NOOP_CTX, log: (_hook: string, message: string) => { lines.push(message); } };
}

/** A ~/.claude look-alike with every input kind the hasher reads, plus decoys. */
function makeClaudeDir(root: string): string {
  mkdirSync(join(root, 'rules', 'sub'), { recursive: true });
  mkdirSync(join(root, 'output-styles'), { recursive: true });
  writeFileSync(join(root, 'CLAUDE.md'), '@RTK.md\n\n# Global rules\n- one\n');
  writeFileSync(join(root, 'RTK.md'), '# RTK\n');
  writeFileSync(join(root, 'rules', 'visual-style.md'), '# Visual style\nline one\nline two\n');
  writeFileSync(join(root, 'rules', 'sub', 'nested.md'), '# nested\n');
  writeFileSync(join(root, 'rules', 'visual-style.md.bak-2026-08-19'), 'decoy backup\n');
  writeFileSync(join(root, 'settings.json'), JSON.stringify({ outputStyle: 'Yonatan' }));
  writeFileSync(join(root, 'output-styles', 'yonatan.md'), '---\nname: Yonatan\n---\nAnswer first.\n');
  writeFileSync(join(root, 'output-styles', 'terse.md'), '---\nname: Terse\n---\nShort.\n');
  return root;
}

function hashOf(dir: string): string {
  const r = computeRulesHash(dir);
  if (!r.ok) throw new Error(`expected a hash, got: ${r.reason}`);
  return r.hash;
}

/** Build the installed plugin layout under `root`; returns the bundle path. */
function makeInstalledLayout(root: string, opts: { dotManifest?: string; rootManifest?: string }): string {
  mkdirSync(join(root, 'hooks', 'dist'), { recursive: true });
  // The hooks package.json is NOT the plugin version (it says 1.0.0 on 10.13.0).
  writeFileSync(join(root, 'hooks', 'package.json'), JSON.stringify({ name: '@orchestkit/hooks', version: '1.0.0' }));
  const bundle = join(root, 'hooks', 'dist', 'lifecycle.mjs');
  writeFileSync(bundle, '// bundle\n');
  if (opts.dotManifest) {
    mkdirSync(join(root, '.claude-plugin'), { recursive: true });
    writeFileSync(join(root, '.claude-plugin', 'plugin.json'), JSON.stringify({ name: 'ork', version: opts.dotManifest }));
  }
  if (opts.rootManifest) {
    writeFileSync(join(root, 'plugin.json'), JSON.stringify({ name: 'ork', version: opts.rootManifest }));
  }
  return bundle;
}

describe('session stamp: ork_version resolver', () => {
  let work: string;

  beforeEach(() => {
    work = mkdtempSync(join(tmpdir(), 'ork-stamp-'));
  });

  afterEach(() => {
    rmSync(work, { recursive: true, force: true });
  });

  it('reads the version from .claude-plugin/plugin.json in the installed layout', () => {
    const bundle = makeInstalledLayout(join(work, 'ork', '10.13.0'), { dotManifest: '10.13.0', rootManifest: '10.13.0' });
    const got = getOrkVersion(bundle);
    expect(got).toEqual(expect.objectContaining({ ok: true, version: '10.13.0' }));
  });

  it('falls back to the root plugin.json when .claude-plugin/ is absent', () => {
    const bundle = makeInstalledLayout(join(work, 'ork', '9.9.9'), { rootManifest: '9.9.9' });
    const got = getOrkVersion(bundle);
    expect(got).toEqual(expect.objectContaining({ ok: true, version: '9.9.9' }));
  });

  it('never reports the hooks package.json version as the plugin version', () => {
    const bundle = makeInstalledLayout(join(work, 'ork', '10.13.0'), { dotManifest: '10.13.0' });
    const got = getOrkVersion(bundle);
    expect(got.ok && got.version).not.toBe('1.0.0');
  });

  it('returns an explicit failure, not a version, when no manifest exists', () => {
    const deep = join(work, 'a', 'b', 'c', 'd', 'e', 'f', 'g');
    mkdirSync(deep, { recursive: true });
    const got = getOrkVersion(join(deep, 'lifecycle.mjs'));
    expect(got.ok).toBe(false);
    if (!got.ok) expect(got.reason.length).toBeGreaterThan(0);
  });

  // The real layout on this machine, read only. Skipped (with the reason in the
  // title) on a host that has no installed ork plugin, such as CI.
  const cacheRoot = join(homedir(), '.claude', 'plugins', 'cache', 'orchestkit', 'ork');
  const installed = existsSync(cacheRoot)
    ? readdirSync(cacheRoot).filter(v => existsSync(join(cacheRoot, v, 'hooks', 'dist', 'lifecycle.mjs')))
    : [];

  it.skipIf(installed.length === 0)(
    'resolves the REAL installed plugin layout under ~/.claude/plugins/cache/orchestkit/ork (skipped: none installed)',
    () => {
      expect(installed.length).toBeGreaterThan(0);
      for (const version of installed) {
        const bundle = join(cacheRoot, version, 'hooks', 'dist', 'lifecycle.mjs');
        const got = getOrkVersion(bundle);
        expect(got).toEqual(expect.objectContaining({ ok: true, version }));
      }
    },
  );
});

describe('session stamp: rules hash', () => {
  let work: string;

  beforeEach(() => {
    work = mkdtempSync(join(tmpdir(), 'ork-rules-'));
  });

  afterEach(() => {
    rmSync(work, { recursive: true, force: true });
  });

  it('hashes CLAUDE.md, its @imports, rules/**/*.md and the active style, in that order', () => {
    const dir = makeClaudeDir(work);
    const r = computeRulesHash(dir);
    expect(r.ok).toBe(true);
    if (!r.ok) return;
    expect(r.hash).toMatch(/^[0-9a-f]{64}$/);
    expect(r.files).toEqual([
      'CLAUDE.md',
      'RTK.md',
      'rules/sub/nested.md',
      'rules/visual-style.md',
      'output-styles/yonatan.md',
    ]);
  });

  it('is stable with no edit and changes with a one-line rule edit (paired)', () => {
    const dir = makeClaudeDir(work);
    const before = hashOf(dir);
    expect(hashOf(dir)).toBe(before);

    const rule = join(dir, 'rules', 'visual-style.md');
    const original = readFileSync(rule, 'utf8');
    writeFileSync(rule, original.replace('line two', 'line two, edited'));
    const edited = hashOf(dir);
    expect(edited).not.toBe(before);

    writeFileSync(rule, original);
    expect(hashOf(dir)).toBe(before);
  });

  it('changes when an @import, the active style or the style selection changes', () => {
    const dir = makeClaudeDir(work);
    const base = hashOf(dir);

    writeFileSync(join(dir, 'RTK.md'), '# RTK v2\n');
    const afterImport = hashOf(dir);
    expect(afterImport).not.toBe(base);

    writeFileSync(join(dir, 'output-styles', 'yonatan.md'), '---\nname: Yonatan\n---\nAnswer first, always.\n');
    const afterStyle = hashOf(dir);
    expect(afterStyle).not.toBe(afterImport);

    writeFileSync(join(dir, 'settings.json'), JSON.stringify({ outputStyle: 'Terse' }));
    expect(hashOf(dir)).not.toBe(afterStyle);
  });

  it('ignores files CC does not load: backups and inactive styles', () => {
    const dir = makeClaudeDir(work);
    const base = hashOf(dir);
    writeFileSync(join(dir, 'rules', 'visual-style.md.bak-2026-08-19'), 'changed decoy\n');
    writeFileSync(join(dir, 'output-styles', 'terse.md'), '---\nname: Terse\n---\nChanged.\n');
    expect(hashOf(dir)).toBe(base);
  });

  it('returns an explicit failure for an empty rule set, never the hash of nothing', () => {
    const r = computeRulesHash(work);
    expect(r.ok).toBe(false);
    if (!r.ok) expect(r.reason).toContain(work);
  });
});

describe('session stamp: registrar writes both fields, failing loud', () => {
  let work: string;
  let prevDb: string | undefined;
  let prevConfig: string | undefined;

  beforeEach(() => {
    work = mkdtempSync(join(tmpdir(), 'ork-stamp-reg-'));
    prevDb = process.env.ORK_SESSION_DB;
    prevConfig = process.env.CLAUDE_CONFIG_DIR;
    process.env.ORK_SESSION_DB = join(work, 'sessions.db');
    __resetDbForTests();
  });

  afterEach(() => {
    __resetDbForTests();
    if (prevDb === undefined) delete process.env.ORK_SESSION_DB;
    else process.env.ORK_SESSION_DB = prevDb;
    if (prevConfig === undefined) delete process.env.CLAUDE_CONFIG_DIR;
    else process.env.CLAUDE_CONFIG_DIR = prevConfig;
    rmSync(work, { recursive: true, force: true });
  });

  it('stores error tokens and logs one line each when nothing resolves', () => {
    const lines: string[] = [];
    const deep = join(work, 'a', 'b', 'c', 'd', 'e', 'f', 'g');
    mkdirSync(deep, { recursive: true });
    const empty = join(work, 'empty-claude');
    mkdirSync(empty);
    const stamp = computeStamp(capturingCtx(lines), { bundleFile: join(deep, 'lifecycle.mjs'), claudeDir: empty });
    expect(stamp).toEqual({ ork_version: ORK_VERSION_UNRESOLVED, rules_hash: RULES_HASH_EMPTY });
    expect(lines.filter(l => l.startsWith(`${ORK_VERSION_UNRESOLVED}:`))).toHaveLength(1);
    expect(lines.filter(l => l.startsWith(`${RULES_HASH_EMPTY}:`))).toHaveLength(1);
    expect(lines).toHaveLength(2);
  });

  it('logs nothing when both resolve', () => {
    const lines: string[] = [];
    const bundle = makeInstalledLayout(join(work, 'ork', '10.13.0'), { dotManifest: '10.13.0' });
    const stamp = computeStamp(capturingCtx(lines), { bundleFile: bundle, claudeDir: makeClaudeDir(join(work, 'c')) });
    expect(stamp.ork_version).toBe('10.13.0');
    expect(stamp.rules_hash).toMatch(/^[0-9a-f]{64}$/);
    expect(lines).toEqual([]);
  });

  it('writes a non-NULL ork_version and rules_hash on the session row', () => {
    const claudeDir = makeClaudeDir(join(work, 'claude'));
    process.env.CLAUDE_CONFIG_DIR = claudeDir;
    const input = {
      hook_event: 'SessionStart',
      tool_name: '',
      session_id: 's-stamp',
      tool_input: {},
      project_dir: work,
    } as HookInput;
    sessionRegistrar(input, NOOP_CTX);

    // From the source tree the nearest manifest is the repo's plugin.json.
    const repoManifest = JSON.parse(
      readFileSync(fileURLToPath(new URL('../../../../../plugin.json', import.meta.url)), 'utf8'),
    ) as { version: string };

    const db = new DatabaseSync(join(work, 'sessions.db'), { readOnly: true });
    const row = db
      .prepare('SELECT ork_version, rules_hash FROM sessions WHERE sid=?')
      .get('s-stamp') as { ork_version: string | null; rules_hash: string | null } | undefined;
    db.close();
    expect(row).toBeDefined();
    expect(row?.ork_version).toBe(repoManifest.version);
    expect(row?.rules_hash).toBe(hashOf(claudeDir));
  });
});
